import os
import boto3
from botocore.exceptions import ClientError

def detect_image_text(payload, config=None):
    config = config or {}
    # Initialize AWS Textract client
    textract_client = boto3.client(
        'textract',
        region_name=config.get('region', 'us-east-1'),
        aws_access_key_id=config.get('aws_access_key_id'),
        aws_secret_access_key=config.get('aws_secret_access_key')
    )

    # Process the image using Textract
    try:
        if isinstance(payload, str):
            # Assume payload is a file path
            with open(payload, 'rb') as image_file:
                image_bytes = image_file.read()
        else:
            # Assume payload is bytes
            image_bytes = payload

        response = textract_client.detect_document_text(Document={'Bytes': image_bytes})
        result = []

        # Extract text blocks from the response
        for item in response.get('Blocks', []):
            if item['BlockType'] == 'LINE':
                result.append({
                    'text': item['Text'],
                    'confidence': item.get('Confidence', 0),
                    'bounding_box': item.get('Geometry', {}).get('BoundingBox', {})
                })

    except ClientError as e:
        raise Exception(f"Textract error: {str(e)}")

    return result
